from build_common import E

def form(site):

    def field(ident, name, label, typ='text', required=False, autocomplete='', placeholder=''):
        return f'''<div class="field"><label for="{ident}">{label}</label><input id="{ident}" name="{name}" type="{typ}" {('required' if required else '')} autocomplete="{autocomplete or 'off'}" maxlength="180" placeholder="{E(placeholder)}" aria-describedby="{ident}-error"><p class="error" id="{ident}-error"></p></div>'''
    opts = [('', 'Choose a topic (optional)'), ('unsure', 'I’m not sure'), ('symptom', 'Something feels wrong'), ('service', 'Service or inspection planning'), ('prebuy', 'Buying an airplane'), ('records', 'Records review'), ('equipment', 'Propeller or avionics help'), ('eprops', 'Propeller / E-PROPS'), ('avionics', 'Avionics / electrical'), ('notice', 'ROTAX bulletin or notice: applicability review')]
    return f'''<div class="container intake-layout"><div class="form-card"><p id="topic-prefill" class="source-note" hidden></p><form id="aircraft-intake-form" action="{site['form_action']}" method="POST" accept-charset="UTF-8"><div id="form-status" class="form-status" role="status" aria-live="polite" tabindex="-1" hidden></div><fieldset><legend>Start your inquiry</legend><p class="helper">Required: name, the selected reply method’s contact detail, and your message.</p><div class="field-grid">{field('support-name', 'name', 'Name (required)', required=True, autocomplete='name')}<div class="field"><label for="support-method">Preferred reply method</label><select id="support-method" name="preferred_contact" required><option value="email">Email</option><option value="phone" disabled>Phone call</option><option value="text" disabled>Text message</option></select></div>{field('support-email', 'email', 'Email<span id="email-required"> (required)</span>', 'email', required=True, autocomplete='email')}{field('support-phone', 'best_contact', 'Phone<span id="phone-required"></span>', 'tel', autocomplete='tel')}<div class="field wide"><label for="support-message">What is happening, or what are you planning? (required)</label><textarea id="support-message" name="message" required maxlength="8000" aria-describedby="support-message-error" placeholder="A brief description is enough. Technical details can follow."></textarea><p class="error" id="support-message-error"></p></div><div class="field"><label for="support-topic">Topic (optional)</label><select name="need_type" id="support-topic">{''.join((f'<option value="{v}">{E(t)}</option>' for v, t in opts))}</select></div><div class="field"><label for="support-urgency">Timing (optional)</label><select name="timeline_urgency" id="support-urgency"><option value="">Select if useful</option><option>Planning ahead</option><option>As soon as practical</option><option>Aircraft is down</option><option>Specific deadline — explain in message</option></select></div></div></fieldset><details class="optional-details"><summary>Aircraft details, if known (optional)</summary><div class="field-grid">{field('support-aircraft', 'aircraft_model', 'Aircraft model', placeholder='Unknown is fine')}{field('support-tail', 'n_number', 'Tail number (optional)')}{field('support-location', 'aircraft_location', 'Airport / location', placeholder='Unknown is fine')}{field('support-engine', 'engine_model', 'Engine model', placeholder='Unknown is fine')}</div></details><div class="hp" aria-hidden="true"><label for="support-hp">Leave empty</label><input id="support-hp" name="_gotcha" tabindex="-1" autocomplete="off"></div><input type="hidden" name="_subject" value="Lima Charlie Aero aircraft inquiry"><div class="actions"><button class="button" type="submit">Send inquiry</button></div><p class="helper">This begins an inquiry; an appointment and work scope still need confirmation. Records or photos may be requested afterward. <a href="/privacy">Privacy and form handling</a></p></form>
<details id="native-phone"><summary>Request a phone or text reply instead</summary>
<form action="{site['form_action']}" method="post">
<label>Name (required)<input name="name" required autocomplete="name"></label>
<label>Reply by<select name="preferred_contact"><option value="phone">Phone call</option><option value="text">Text</option></select></label>
<label>Phone (required)<input type="tel" name="best_contact" required autocomplete="tel" pattern="(?:[^0-9A-Za-z]*[0-9]){{7,15}}[^0-9A-Za-z]*" title="Enter a phone number with 7 to 15 digits."></label>
<label>Your message (required)<textarea name="message" required maxlength="8000"></textarea></label>
<button type="submit" class="button">Send inquiry</button></form></details></div><aside class="side-card"><h2>Prefer to talk?</h2><p>You can describe the issue without a diagnosis.</p><a class="button" href="tel:{site['phone']}">Call {site['display_phone']}</a><div class="actions"><a href="sms:{site['phone']}">Text the Shop</a><a href="mailto:{site['email']}">Email the Shop</a></div><p>For time-sensitive concerns, call or text. This form is not a flight-readiness assessment.</p></aside></div>'''
